const COST_RE = /^[0-9]+$/

export class GraphError extends Error {}

/**
 * Parses the graph text into a map of task costs and a map of dependency
 * sets. Throws GraphError for any malformed directive or unknown task
 * reference, per the specification's exact messages (without the leading
 * "error: ").
