  const tasks = new Map()
  const deps = new Map()
  const depEdgesInOrder = []

  lines.forEach((raw, idx) => {
    const lineNo = idx + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new GraphError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new GraphError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new GraphError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new GraphError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, Number(costStr))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new GraphError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const depNames = words.slice(2)
      depEdgesInOrder.push({ name, depNames })
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (const d of depNames) set.add(d)
    } else {
      throw new GraphError(`line ${lineNo}: unknown directive ${directive}`)
    }
  })

  for (const { name, depNames } of depEdgesInOrder) {
    if (!tasks.has(name)) throw new GraphError(`unknown task ${name}`)
    for (const d of depNames) {
      if (!tasks.has(d)) throw new GraphError(`unknown task ${d}`)
    }
  }

  return { tasks, deps }
}
"}

