 * Cycle detection for the dependency graph. Runs a depth-first search from
 * each task in ascending name order, walking each task's dependencies in
 * ascending name order, and reports the first cycle re-entered.
 */

export function findCycle({ tasks, deps }) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, 'active')
    stack.push(node)
    const children = [...(deps.get(node) || [])].sort()
    for (const child of children) {
      const childState = state.get(child)
      if (childState === 'active') {
        const idx = stack.indexOf(child)
        return [...stack.slice(idx), child]
      }
      if (childState !== 'done') {
        const found = visit(child)
        if (found) return found
      }
    }
    state.set(node, 'done')
    stack.pop()
    return null
  }

  for (const start of names) {
    if (state.get(start) === 'done') continue
    const found = visit(start)
    if (found) return found
  }
  return null
}
"}

