 * Computes the unlimited-worker schedule: each task's start, finish and
 * wave depth, plus the overall makespan. Assumes the graph is acyclic.
 */

export function computeSchedule({ tasks, deps }) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const ds = deps.get(name)
    let s = 0
    let d = 0
    if (ds) {
      for (const dep of ds) {
        compute(dep)
        if (finish.get(dep) > s) s = finish.get(dep)
        if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
      }
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}

export function totalOf(finish) {
  let total = 0
  for (const f of finish.values()) if (f > total) total = f
  return total
}

export function formatWaves({ depth, finish }) {
  const groups = new Map()
  for (const [name, d] of depth) {
    if (!groups.has(d)) groups.set(d, [])
    groups.get(d).push(name)
  }
  const maxDepth = groups.size ? Math.max(...groups.keys()) : -1
  let out = ''
  for (let k = 0; k <= maxDepth; k++) {
    const names = (groups.get(k) || []).sort()
    out += `wave ${k}: ${names.join(' ')}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}

export function formatExplain({ start, finish, depth }) {
  const names = [...start.keys()].sort()
  let out = ''
  for (const name of names) {
    out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}
"}

