{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-BjKgnS/src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily starting
 * the highest-priority ready task on the lowest-indexed free worker at each
 * instant. Priority is the cost of the longest chain of costs starting at
 * a task and running forward through its dependents to a task nothing
 * depends on.
 */

function computePriorities(tasks, dependents) {
  const priority = new Map()
  const visiting = new Set()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    visiting.add(name)
    let best = 0
    for (const dependent of dependents.get(name) || []) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    visiting.delete(name)
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

export function packWorkers({ tasks, deps }, workerCount) {
  const dependents = new Map()
  for (const [name, ds] of deps) {
    for (const d of ds) {
      if (!dependents.has(d)) dependents.set(d, new Set())
      dependents.get(d).add(name)
    }
  }

  const priority = computePriorities(tasks, dependents)

  const finishTime = new Map()
  const remaining = new Set(tasks.keys())
  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let time = 0

  const isReady = (name, at) => {
    const ds = deps.get(name)
    if (!ds) return true
    for (const d of ds) {
      if (!finishTime.has(d) || finishTime.get(d) > at) return false
    }
    return true
  }

  while (remaining.size > 0) {
    let startedSomething = true
    while (startedSomething) {
      startedSomething = false

      let freeIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= time) { freeIdx = i; break }
      }
      if (freeIdx === -1) break

      let chosen = null
      for (const name of remaining) {
        if (!isReady(name, time)) continue
        if (chosen === null) {
          chosen = name
          continue
        }
        const p = priority.get(name)
        const best = priority.get(chosen)
        if (p > best || (p === best && name < chosen)) chosen = name
      }
      if (chosen === null) break

      const cost = tasks.get(chosen)
      const finish = time + cost
      workerLog[freeIdx].push({ name: chosen, start: time, finish })
      workerFreeAt[freeIdx] = finish
      finishTime.set(chosen, finish)
      remaining.delete(chosen)
      startedSomething = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > time && workerFreeAt[i] < next) next = workerFreeAt[i]
    }
    if (next === Infinity) break
    time = next
  }

  let makespan = 0
  for (const f of finishTime.values()) if (f > makespan) makespan = f

  return { workerLog, makespan }
}

export function formatPack({ workerLog, makespan }) {
  let out = ''
  workerLog.forEach((log, i) => {
    const parts = log.map((t) => ` ${t.name}@${t.start}-${t.finish}`).join('')
    out += `worker ${i}:${parts}\n`
  })
  out += `makespan ${makespan}\n`
  return out
}
"}

